	private static final class OverlayUpdates implements ImmutablePagedQuadCsfIndex.RowUpdateSource {
		private final LatestRows rows;
		private final LmdbAdjacencyContextCatalog contexts;
		private final int[] records;
		private final int[] partitions;
		private final int[] order;
		private final long[] pairCounts;
		private final LmdbAdjacencyRunCodec.RunCursor cursor = new LmdbAdjacencyRunCodec.RunCursor();
		private int cursorRecord = -1;

		OverlayUpdates(LatestRows rows, LmdbAdjacencyContextCatalog contexts, int[] records, int[] partitions,
				int[] order) {
			this.rows = rows;
			this.contexts = contexts;
			this.records = records;
			this.partitions = partitions;
			this.order = order;
			this.pairCounts = new long[records.length];
			Arrays.fill(pairCounts, -1);
			for (int i = 1; i < order.length; i++) {
				int before = order[i - 1];
				int current = order[i];
				int cmp = Integer.compare(partitions[before], partitions[current]);
				if (cmp == 0) {
					cmp = Long.compareUnsigned(rows.keys[records[before]], rows.keys[records[current]]);
				}
				if (cmp >= 0) {
					throw new IllegalStateException("folded CSF rows are not unique in partition order");
				}
			}
		}

		@Override
		public int size() {
			return order.length;
		}

		@Override
		public int partitionAt(int index) {
			return partitions[order[index]];
		}

		@Override
		public long rowAt(int index) {
			return rows.keys[records[order[index]]];
		}

		@Override
		public boolean tombstoneAt(int index) {
			return rows.tombstone(records[order[index]]);
		}

		@Override
		public long pairCountAt(int index) {
			int ordered = order[index];
			if (tombstoneAt(index)) {
				return 0;
			}
			long count = pairCounts[ordered];
			if (count < 0) {
				resolve(ordered);
				count = cursor.edgeCount();
				pairCounts[ordered] = count;
			}
			return count;
		}

		@Override
		public int copyPairsAt(int index, long fromOrdinal, int length, long[] neighborTarget, int neighborOffset,
				long[] contextTarget, int contextOffset) {
			int ordered = order[index];
			resolve(ordered);
			return LmdbAdjacencyRunCodec.copy(contexts, cursor, fromOrdinal, length, neighborTarget, neighborOffset,
					contextTarget, contextOffset);
		}

		private void resolve(int ordered) {
			if (cursorRecord == ordered) {
				return;
			}
			int record = records[ordered];
			LmdbAdjacencyDeltaGeneration generation = rows.generation(record);
			long handle = generation.handleAt(rows.generationRow(record));
			if (handle <= 0) {
				throw new IllegalStateException("attempted to resolve a CSF tombstone as a run");
			}
			LmdbAdjacencyRunCodec.resolve(generation.catalog(), handle, cursor);
			cursorRecord = ordered;
		}
	}

	private static void mergeSort(int[] values, int[] scratch, int from, int to, int[] records, int[] partitions,
			long[] keys) {
		if (to - from <= 1) {
			return;
		}
		int mid = (from + to) >>> 1;
		mergeSort(values, scratch, from, mid, records, partitions, keys);
		mergeSort(values, scratch, mid, to, records, partitions, keys);
		System.arraycopy(values, from, scratch, from, to - from);
		int left = from;
		int right = mid;
		for (int out = from; out < to; out++) {
			if (left < mid && (right >= to
					|| compareUpdate(scratch[left], scratch[right], records, partitions, keys) <= 0)) {
				values[out] = scratch[left++];
			} else {
				values[out] = scratch[right++];
			}
		}
	}

	private static int compareUpdate(int left, int right, int[] records, int[] partitions, long[] keys) {
		int cmp = Integer.compare(partitions[left], partitions[right]);
		return cmp != 0 ? cmp : Long.compareUnsigned(keys[records[left]], keys[records[right]]);
	}

	private static int compare(long aKey, int aPlane, long aPredicate, long bKey, int bPlane, long bPredicate) {
		int cmp = Long.compareUnsigned(aKey, bKey);
		if (cmp != 0) {
			return cmp;
		}
		cmp = Integer.compare(aPlane, bPlane);
		return cmp != 0 ? cmp : Long.compareUnsigned(aPredicate, bPredicate);
	}

	private static void sortUnsigned(long[] values) {
		for (int i = 0; i < values.length; i++) {
			values[i] ^= Long.MIN_VALUE;
		}
		Arrays.sort(values);
		for (int i = 0; i < values.length; i++) {
			values[i] ^= Long.MIN_VALUE;
		}
	}
